class TestTrainStrategy:
    def test_train_and_evaluate_produces_model(self, tmp_path):
        from learn_datalake.train_strategy import train_and_evaluate

        labels_path = tmp_path / "labels.jsonl"
        random.seed(42)
        strategies = ["stream_default", "lattice_default", "lattice_strong"]
        with open(labels_path, "w") as f:
            for i in range(300):
                f.write(json.dumps({
                    "features": {
                        "table_style_borderless": random.randint(0, 1),
                        "table_style_bordered": random.randint(0, 1),
                        "domain_scientific": random.randint(0, 1),
                        "domain_defense": random.randint(0, 1),
                        "has_borders": random.randint(0, 1),
                        "category": random.choice(["scientific", "defense", "general"]),
                    },
                    "label": strategies[i % len(strategies)],
                }) + "\n")

        output_dir = tmp_path / "model_output"
        metrics = train_and_evaluate(labels_path, output_dir)

        assert metrics["n_samples"] == 300
        assert metrics["n_classes"] == 3
        assert "accuracy" in metrics
        assert "macro_f1" in metrics
        assert (output_dir / "model.joblib").exists()
        assert (output_dir / "metrics.json").exists()
        assert (output_dir / "label_encoder.joblib").exists()

    def test_train_fails_on_empty_file(self, tmp_path):
        from learn_datalake.train_strategy import train_and_evaluate

        labels_path = tmp_path / "labels.jsonl"
        labels_path.write_text("")

        with pytest.raises(ValueError, match="No records"):
            train_and_evaluate(labels_path, tmp_path / "out")
